/* =====================================================================
   engine.backend.js  —  Engine.Backend   (blueprint §14)

   Generates a real, dependency-free HTTP backend:
     - server.js         : routing table, static files, JSON body parsing,
                           auth middleware, structured error responses.
     - src/services/*.js : a service layer per entity (create/list/get/
                           update/remove) with validation + ownership scoping.
   REST per entity:
     GET  /api/<plural>            list (?limit &offset &<field>=)
     POST /api/<plural>            create           (auth)
     GET  /api/<plural>/:id        read
     PUT  /api/<plural>/:id        update           (auth + owner/admin)
     DELETE /api/<plural>/:id      delete           (auth + owner/admin)

   window.Engine.Backend
     serviceModule(entity)   -> src/services/<entity>.js source
     serverModule(spec)      -> server.js source
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var Schema = function () { return Engine.Schema; };

  function serviceModule(e) {
    var ownerField = (e.fields || []).find(function (f) { return f.type === 'ref' && f.ref === 'user'; });
    var owned = e.ownable && ownerField;
    return [
      "'use strict';",
      "const db = require('../db');",
      "const ENTITY = '" + e.name + "';",
      "",
      "async function list(query, user) {",
      "  const where = {};",
      "  for (const k of Object.keys(query || {})) if (!['limit', 'offset'].includes(k)) where[k] = query[k];",
      owned ? "  if (user && user.role !== 'admin') where." + ownerField.name + " = user.id;" : "  // public listing",
      "  return db.list(ENTITY, { where, limit: query.limit, offset: query.offset });",
      "}",
      "async function get(id) { return db.get(ENTITY, id); }",
      "async function create(input, user) {",
      "  const data = Object.assign({}, input);",
      owned ? "  data." + ownerField.name + " = user.id;" : "",
      "  return db.create(ENTITY, data);",
      "}",
      "async function update(id, input, user) {",
      "  const row = await db.get(ENTITY, id);",
      "  if (!row) return null;",
      owned ? "  if (user.role !== 'admin' && row." + ownerField.name + " !== user.id) throw Object.assign(new Error('forbidden'), { status: 403 });" : "",
      "  return db.update(ENTITY, id, input);",
      "}",
      "async function remove(id, user) {",
      "  const row = await db.get(ENTITY, id);",
      "  if (!row) return false;",
      owned ? "  if (user.role !== 'admin' && row." + ownerField.name + " !== user.id) throw Object.assign(new Error('forbidden'), { status: 403 });" : "",
      "  return db.remove(ENTITY, id);",
      "}",
      "module.exports = { list, get, create, update, remove, owned: " + (!!owned) + " };",
      ""
    ].filter(function (l) { return l !== ''; }).join('\n') + '\n';
  }

  function serverModule(spec) {
    var s = Schema().normalizeSpec(spec);
    var withAuth = s.auth;
    var withJobs = !!spec.jobs;
    var withGraphQL = spec.api === 'graphql';
    var withWS = !!spec.websocket;
    var resources = s.entities.filter(function (e) { return e.name !== 'user' && e.name !== 'session' && e.name !== 'job'; });
    var portArg = "(process.argv.find((a) => a.startsWith('--port=')) || '').split('=')[1]";
    var lines = [
      "'use strict';",
      "// " + s.name + " — dependency-free HTTP API + static server.",
      "// Generated by CodeSovereign (Engine.Backend). Real routing, auth, CRUD.",
      "const http = require('http');",
      "const fs = require('fs');",
      "const path = require('path');",
      "const db = require('./src/db');",
      withAuth ? "const auth = require('./src/auth');" : "",
      withJobs ? "const queue = require('./src/queue');" : "",
      withJobs ? "const events = require('./src/events');" : "",
      withGraphQL ? "const { graphqlHandler } = require('./src/graphql/handler');" : "",
      withWS ? "const { wsAttach, broadcast } = require('./src/ws');" : "",
      ""
    ];
    resources.forEach(function (e) {
      lines.push("const svc_" + e.name + " = require('./src/services/" + e.name + "');");
    });
    lines.push("");
    lines.push("const PORT = process.env.PORT || " + portArg + " || 4319;");
    lines.push("const PUBLIC = path.join(__dirname, 'public');");
    lines.push("const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml', '.json': 'application/json' };");
    lines.push("");
    lines.push("function send(res, code, body, type) {");
    lines.push("  const s = typeof body === 'string' ? body : JSON.stringify(body);");
    lines.push("  res.writeHead(code, { 'content-type': type || 'application/json' }); res.end(s);");
    lines.push("}");
    lines.push("function readBody(req) { return new Promise((resolve) => { let r = ''; req.on('data', (c) => { r += c; if (r.length > 1e6) req.destroy(); }); req.on('end', () => { try { resolve(r ? JSON.parse(r) : {}); } catch (_) { resolve({}); } }); }); }");
    lines.push("");
    lines.push("// simple fixed-window rate limiter (per IP): 120 req / 60s");
    lines.push("const rl = new Map();");
    lines.push("function rateLimit(req) {");
    lines.push("  const ip = (req.headers['x-forwarded-for'] || req.socket.remoteAddress || 'x').split(',')[0].trim();");
    lines.push("  const now = Date.now(); const e = rl.get(ip) || { n: 0, t: now };");
    lines.push("  if (now - e.t > 60000) { e.n = 0; e.t = now; }");
    lines.push("  e.n++; rl.set(ip, e);");
    lines.push("  return e.n <= 120;");
    lines.push("}");
    lines.push("");
    lines.push("// ---- ops: uptime, request/response counters, structured access log ----");
    lines.push("const STARTED = Date.now();");
    lines.push("const metrics = { requests: 0, inflight: 0, byStatus: {}, byMethod: {} };");
    lines.push("const LOG_SILENT = process.env.LOG === 'silent' || process.env.NODE_ENV === 'test';");
    lines.push("function observe(req, res, t0) {");
    lines.push("  metrics.requests++; metrics.inflight++;");
    lines.push("  metrics.byMethod[req.method] = (metrics.byMethod[req.method] || 0) + 1;");
    lines.push("  res.on('finish', () => {");
    lines.push("    metrics.inflight--;");
    lines.push("    const cls = (res.statusCode / 100 | 0) + 'xx';");
    lines.push("    metrics.byStatus[cls] = (metrics.byStatus[cls] || 0) + 1;");
    lines.push("    if (!LOG_SILENT) { try { console.log(JSON.stringify({ t: new Date().toISOString(), level: res.statusCode >= 500 ? 'error' : 'info', msg: 'request', method: req.method, path: (req.url || '').split('?')[0], status: res.statusCode, ms: Date.now() - t0 })); } catch (_) {} }");
    lines.push("  });");
    lines.push("}");
    lines.push("function metricsText() {");
    lines.push("  const up = (Date.now() - STARTED) / 1000;");
    lines.push("  let out = '# HELP app_uptime_seconds Process uptime.\\n# TYPE app_uptime_seconds gauge\\napp_uptime_seconds ' + up.toFixed(1) + '\\n';");
    lines.push("  out += '# HELP app_requests_total Requests received.\\n# TYPE app_requests_total counter\\napp_requests_total ' + metrics.requests + '\\n';");
    lines.push("  out += '# TYPE app_requests_inflight gauge\\napp_requests_inflight ' + metrics.inflight + '\\n';");
    lines.push("  for (const k of Object.keys(metrics.byStatus)) out += 'app_responses_total{class=\"' + k + '\"} ' + metrics.byStatus[k] + '\\n';");
    lines.push("  for (const k of Object.keys(metrics.byMethod)) out += 'app_requests_by_method_total{method=\"' + k + '\"} ' + metrics.byMethod[k] + '\\n';");
    lines.push("  const m = process.memoryUsage(); out += 'app_memory_rss_bytes ' + m.rss + '\\n';");
    lines.push("  return out;");
    lines.push("}");
    lines.push("");
    lines.push("const server = http.createServer(async (req, res) => {");
    lines.push("  const _t0 = Date.now(); observe(req, res, _t0);");
    lines.push("  const u = new URL(req.url, 'http://localhost'); const seg = u.pathname.split('/').filter(Boolean);");
    lines.push("  const q = Object.fromEntries(u.searchParams);");
    lines.push("  try {");
    lines.push("    if (u.pathname === '/healthz') return send(res, 200, { ok: true, uptime_s: Math.round((Date.now() - STARTED) / 1000) });");
    lines.push("    if (u.pathname === '/readyz') { try { " + (resources[0] || withAuth ? "await db.list('" + (resources[0] ? resources[0].name : 'user') + "', { limit: 1 }); " : "") + "return send(res, 200, { ready: true }); } catch (e) { return send(res, 503, { ready: false, error: String(e.message || e) }); } }");
    lines.push("    if (u.pathname === '/metrics') return send(res, 200, metricsText(), 'text/plain; version=0.0.4');");
    lines.push("    if (u.pathname.startsWith('/api/') && !rateLimit(req)) return send(res, 429, { error: 'rate limit exceeded' });");
    if (withGraphQL) {
      lines.push("    if (u.pathname === '/graphql') return graphqlHandler(req, res, req.method === 'GET' ? '' : await new Promise((rs) => { let b = ''; req.on('data', (c) => b += c); req.on('end', () => rs(b)); }));");
    }
    if (withAuth) {
      lines.push("    await auth.attachUser(req);");
      lines.push("    if (seg[0] === 'api' && seg[1] === 'auth') {");
      lines.push("      if (seg[2] === 'register' && req.method === 'POST') { const b = await readBody(req); return send(res, 201, await auth.register(b.email, b.password)); }");
      lines.push("      if (seg[2] === 'login' && req.method === 'POST') { const b = await readBody(req); return send(res, 200, await auth.login(b.email, b.password)); }");
      lines.push("      if (seg[2] === 'logout' && req.method === 'POST') { return send(res, 200, await auth.logout(auth.bearer(req))); }");
      lines.push("      if (seg[2] === 'me' && req.method === 'GET') { return send(res, 200, { user: req.user || null }); }");
      lines.push("      return send(res, 404, { error: 'not found' });");
      lines.push("    }");
    }
    if (withJobs) {
      lines.push("    if (seg[0] === 'api' && seg[1] === 'events' && req.method === 'GET') return events.subscribe(res);");
      lines.push("    if (seg[0] === 'api' && seg[1] === 'jobs') {");
      lines.push("      if (seg[2] === 'stats' && req.method === 'GET') return send(res, 200, await queue.stats());");
      lines.push("      if (!seg[2] && req.method === 'POST') { " + (withAuth ? "auth.requireAuth(req); " : "") + "const b = await readBody(req); const j = await queue.enqueue(b.type, b.payload); return send(res, 202, j); }");
      lines.push("    }");
    }
    lines.push("    if (seg[0] === 'api') {");
    lines.push("      const map = {" + resources.map(function (e) { return "\n        '" + e.table + "': { svc: svc_" + e.name + ", ent: '" + e.name + "' }"; }).join(',') + "\n      };");
    lines.push("      const r = map[seg[1]];");
    lines.push("      if (r) {");
    lines.push("        const id = seg[2];");
    lines.push("        if (!id && req.method === 'GET') return send(res, 200, await r.svc.list(q, " + (withAuth ? "req.user" : "null") + "));");
    if (withAuth) lines.push("        if (!id && req.method === 'POST') { auth.requireAuth(req); return send(res, 201, await r.svc.create(await readBody(req), req.user)); }");
    else lines.push("        if (!id && req.method === 'POST') return send(res, 201, await r.svc.create(await readBody(req), null));");
    lines.push("        if (id && req.method === 'GET') { const row = await r.svc.get(id); return row ? send(res, 200, row) : send(res, 404, { error: 'not found' }); }");
    lines.push("        if (id && (req.method === 'PUT' || req.method === 'PATCH')) { " + (withAuth ? "auth.requireAuth(req); " : "") + "const row = await r.svc.update(id, await readBody(req), " + (withAuth ? "req.user" : "null") + "); return row ? send(res, 200, row) : send(res, 404, { error: 'not found' }); }");
    lines.push("        if (id && req.method === 'DELETE') { " + (withAuth ? "auth.requireAuth(req); " : "") + "const ok = await r.svc.remove(id, " + (withAuth ? "req.user" : "null") + "); return send(res, ok ? 200 : 404, { ok }); }");
    lines.push("      }");
    lines.push("      return send(res, 404, { error: 'unknown resource' });");
    lines.push("    }");
    lines.push("    // static");
    lines.push("    const rel = u.pathname === '/' ? '/index.html' : u.pathname;");
    lines.push("    const f = path.join(PUBLIC, rel.replace(/\\.\\./g, ''));");
    lines.push("    if (f.startsWith(PUBLIC) && fs.existsSync(f) && fs.statSync(f).isFile())");
    lines.push("      return send(res, 200, fs.readFileSync(f, 'utf8'), MIME[path.extname(f)] || 'text/plain');");
    lines.push("    send(res, 404, { error: 'not found' });");
    lines.push("  } catch (e) {");
    lines.push("    send(res, e.status || 500, { error: String(e.message || e) });");
    lines.push("  }");
    lines.push("});");
    lines.push("");
    if (withWS) lines.push("wsAttach(server, { path: '/ws' });");
    lines.push("if (require.main === module) db.migrate().then(() => server.listen(PORT, () => console.log('" + s.name + " on http://localhost:' + PORT)));");
    lines.push("module.exports = { server" + (withWS ? ", broadcast" : "") + " };");
    lines.push("");
    return lines.filter(function (l, i) { return !(l === '' && lines[i - 1] === ''); }).join('\n');
  }

  Engine.Backend = { serviceModule: serviceModule, serverModule: serverModule };
  console.info('[Backend] REST backend generator ready — Engine.Backend');
})();
